fn read_partition(path: &Path) -> Result<CapturedMemberDeclarations, EntitySearchPipelineError> {
    let member_id = path
        .file_stem()
        .and_then(|name| name.to_str())
        .ok_or_else(|| read_error("partition filename must contain a member UUID"))?
        .parse::<Uuid>()
        .map_err(read_error)?;
